// Helper: parse price string like "R1,250" to number
function parsePrice(s) { return parseFloat((s || "0").replace(/[^0-9.]/g, "")) || 0; }
function formatPrice(n) { return "R" + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }

const ANATOMIC_SHIRT_SIZES = ["XS", "S", "M", "L", "XL", "XXL"];

function isAnatomicShirt(product) {
  if (product?.isSaleItem) return false;
  const name = String(product?.name || "").toLowerCase();
  const sub = String(product?.subcategory || "").toLowerCase().replace(/_/g, "-");
  if (sub.includes("western-shirt") || sub.includes("button-shirt")) return true;
  if (!name.includes("shirt")) return false;
  return name.includes("anatomic") || name.includes("button shirt") || name.includes("button");
}

function getProductSizes(product) {
  if (!isAnatomicShirt(product)) return [];
  const custom = product?.sizes;
  if (Array.isArray(custom) && custom.length > 0) return custom.filter(Boolean);
  return ANATOMIC_SHIRT_SIZES;
}

function getProductStyles(product) {
  if (!isAnatomicShirt(product)) return [];
  const images = product?.images || [];
  const labels = product?.image_labels || product?.imageLabels || [];
  return images.map((src, i) => ({
    index: i,
    label: (labels[i] || "").trim() || `Style ${i + 1}`,
    image: src,
  }));
}

function productNeedsOrderOptions(product) {
  return isAnatomicShirt(product);
}

// Normalizes a stall item + a sale's % discount into an object OrderFormPage
// can select/checkout the same as a regular product.
function toSaleProduct(stallItem, discountPercent) {
  const original = parsePrice(stallItem.price);
  const discounted = Math.round(Math.max(0, original - (original * discountPercent / 100)));
  return {
    id: `sale-${stallItem.id}`,
    isSaleItem: true,
    stallItemId: stallItem.id,
    name: stallItem.name,
    category: stallItem.category || "other",
    images: stallItem.image ? [stallItem.image] : [],
    price: formatPrice(discounted).replace(/\.00$/, ""),
    originalPrice: stallItem.price,
    discountPercent,
    stock: Math.max(0, stallItem.stock ?? 0),
  };
}

function formatOrderItemLabel(item) {
  const extras = [];
  if (item.size) extras.push(`Size ${item.size}`);
  if (item.styleLabel) extras.push(item.styleLabel);
  return extras.length ? `${item.name} (${extras.join(" · ")})` : item.name;
}

// Resize/compress large images before upload to improve upload speed.
async function optimizeImageForUpload(file) {
  const MAX_DIMENSION = 2000;
  const QUALITY = 0.82;
  const SKIP_IF_SMALLER_THAN = 900 * 1024;

  if (!file || file.size <= SKIP_IF_SMALLER_THAN || !isImageFile(file)) return file;

  try {
    const dataUrl = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });

    const img = await new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = reject;
      image.src = dataUrl;
    });

    const scale = Math.min(1, MAX_DIMENSION / Math.max(img.width, img.height));
    const width = Math.max(1, Math.round(img.width * scale));
    const height = Math.max(1, Math.round(img.height * scale));

    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    if (!ctx) return file;
    ctx.drawImage(img, 0, 0, width, height);

    const hasAlpha = (file.type || "").includes("png");
    const outType = hasAlpha ? "image/png" : "image/jpeg";
    const outExt = hasAlpha ? "png" : "jpg";
    const blob = await new Promise((resolve) => canvas.toBlob(resolve, outType, QUALITY));
    if (!blob) return file;
    if (blob.size >= file.size) return file;

    const baseName = (file.name || "image").replace(/\.[^.]+$/, "");
    return new File([blob], `${baseName}.${outExt}`, { type: outType, lastModified: Date.now() });
  } catch (err) {
    console.warn("Image optimization skipped:", err);
    return file;
  }
}

async function uploadImageBatch(bucket, files) {
  const optimized = await Promise.all(files.map((file) => optimizeImageForUpload(file)));
  return Promise.all(optimized.map((file) => uploadImage(bucket, file)));
}

