function ProductImage({ name, category, images, size = 280 }) {
  const imgs = images || [];
  if (imgs.length > 0) {
    return (
      <div style={{ width: "100%", aspectRatio: "1", borderRadius: 8, overflow: "hidden", background: BRAND.offWhite }}>
        <img src={imgs[0]} alt={name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
      </div>
    );
  }
  const palettes = {
    bridles: { bg: "#0a0a0a", fg: BRAND.teal, accent: "#1a1a2e" },
    breastplates: { bg: "#0c0c1a", fg: BRAND.purple, accent: "#1a0a30" },
    reins: { bg: "#001a1f", fg: BRAND.teal, accent: "#003040" },
    bags: { bg: "#0a0a0a", fg: BRAND.purple, accent: "#1a1a2e" },
  };
  const p = palettes[category] || palettes.bags;
  const initials = (name || "").split(" ").map(w => w[0]).join("").slice(0, 2);
  return (
    <div style={{ width: "100%", aspectRatio: "1", background: `linear-gradient(145deg, ${p.bg}, ${p.accent})`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", borderRadius: 8, position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, opacity: 0.05, background: "repeating-linear-gradient(45deg, transparent, transparent 10px, rgba(255,255,255,0.08) 10px, rgba(255,255,255,0.08) 20px)" }} />
      <div style={{ fontSize: size * 0.16, color: p.fg, fontFamily: "'Montserrat', sans-serif", fontWeight: 800, letterSpacing: 3, opacity: 0.9 }}>{initials}</div>
      <div style={{ fontSize: size * 0.04, color: p.fg, fontFamily: "'Inter', sans-serif", marginTop: 8, textTransform: "uppercase", letterSpacing: 4, opacity: 0.5 }}>{CATEGORIES[category]?.label || titleCaseCategory(category)}</div>
    </div>
  );
}

function ProductGallery({ images, name, category }) {
  const [active, setActive] = useState(0);
  const imgs = images || [];
  if (imgs.length === 0) return <ProductImage name={name} category={category} size={400} />;
  return (
    <div>
      <div style={{ width: "100%", aspectRatio: "1", borderRadius: 10, overflow: "hidden", background: BRAND.offWhite, marginBottom: 12 }}>
        <img src={imgs[active] || imgs[0]} alt={name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block", transition: "opacity 0.3s" }} />
      </div>
      {imgs.length > 1 && (
        <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4 }}>
          {imgs.map((src, i) => (
            <button key={i} onClick={() => setActive(i)} style={{ width: 64, height: 64, borderRadius: 6, overflow: "hidden", border: i === active ? `2px solid ${BRAND.teal}` : "2px solid transparent", cursor: "pointer", flexShrink: 0, padding: 0, background: BRAND.offWhite, transition: "all 0.2s", opacity: i === active ? 1 : 0.6 }}>
              <img src={src} alt={`${name} ${i + 1}`} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

