function AdminStallEventNewPage({ stallItems, onStart, onCancel, showToast }) {
  const [name, setName] = useState("");
  const [counts, setCounts] = useState(() => Object.fromEntries(stallItems.map(i => [i.id, Math.max(0, i.stock || 0)])));
  const setCount = (id, v) => setCounts(c => ({ ...c, [id]: Math.max(0, v) }));

  const grouped = stallItems.reduce((acc, it) => {
    const key = titleCaseCategory(it.category) || "Other";
    (acc[key] = acc[key] || []).push(it);
    return acc;
  }, {});

  const handleStart = () => {
    if (!name.trim()) { showToast("Enter an event name"); return; }
    onStart(name.trim(), stallItems.map(i => ({ stall_item_id: i.id, opening_stock: counts[i.id] ?? Math.max(0, i.stock || 0) })));
  };

  return (
    <div className="fade-in" style={{ maxWidth: 640, margin: "0 auto", padding: "48px 24px 100px" }}>
      <button onClick={onCancel} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Events</button>
      <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 26, color: BRAND.black, fontWeight: 800, marginBottom: 8 }}>Start New Event</h1>
      <p style={{ fontSize: 13, color: BRAND.grey, marginBottom: 24 }}>Enter the show name, then confirm or adjust how many of each item you're bringing today.</p>

      <div style={{ marginBottom: 28 }}>
        <label className="ll-label">Event Name *</label>
        <input className="ll-input" value={name} onChange={e => setName(e.target.value)} placeholder="e.g. SANESA Show — July 2026" />
      </div>

      {stallItems.length === 0 && <p style={{ color: BRAND.grey, fontSize: 14 }}>Add items to your Stall Price List first.</p>}
      {Object.entries(grouped).sort(([a], [b]) => a.localeCompare(b)).map(([cat, items]) => (
        <div key={cat} style={{ marginBottom: 20 }}>
          <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 13, fontWeight: 800, letterSpacing: 1, textTransform: "uppercase", color: BRAND.teal, marginBottom: 10 }}>{cat}</h3>
          {items.map(item => (
            <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 14, padding: "10px 14px", background: BRAND.white, borderRadius: 8, border: `1px solid ${BRAND.greyLight}`, marginBottom: 8 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 14, color: BRAND.black }}>{item.name}</div>
                <div style={{ fontSize: 12, color: BRAND.grey }}>{item.price}</div>
              </div>
              <input
                type="number" min="0" className="ll-input"
                style={{ width: 70, textAlign: "center", padding: "8px 6px" }}
                value={counts[item.id] ?? 0}
                onChange={e => setCount(item.id, parseInt(e.target.value, 10) || 0)}
              />
            </div>
          ))}
        </div>
      ))}

      <div style={{ display: "flex", gap: 12, marginTop: 24 }}>
        <button className="ll-btn ll-btn-primary" style={{ flex: 1, justifyContent: "center" }} onClick={handleStart}>Start Event</button>
        <button className="ll-btn ll-btn-outline" onClick={onCancel}>Cancel</button>
      </div>
    </div>
  );
}

function AdminStallEventDetailPage({ event, onBack, onEnd, onUpdateActualCount, onUndoSale, showToast }) {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [actualCounts, setActualCounts] = useState({});

  const refresh = async () => {
    setLoading(true);
    const data = await db.getStallEventSummary(event.id);
    if (data) {
      setSummary(data);
      setActualCounts(Object.fromEntries((data.eventItems || []).map(ei => [ei.id, ei.actual_count ?? ""])));
    }
    setLoading(false);
  };

  useEffect(() => { refresh(); }, [event.id, event.status]);

  if (loading || !summary) return <div style={{ padding: 60, textAlign: "center", color: BRAND.grey }}>Loading event…</div>;

  const soldByItem = {};
  summary.sales.forEach(s => { soldByItem[s.stall_item_id] = (soldByItem[s.stall_item_id] || 0) + s.quantity; });

  const rows = summary.eventItems.map(ei => {
    const sold = soldByItem[ei.stall_item_id] || 0;
    const remaining = Math.max(0, ei.opening_stock - sold);
    return { ...ei, sold, remaining };
  });

  const totalSold = rows.reduce((s, r) => s + r.sold, 0);
  const totalRevenue = rows.reduce((s, r) => s + r.sold * parsePrice(r.stall_items?.price), 0);

  const handleUndo = async (sale) => {
    await onUndoSale(sale);
    refresh();
  };

  const saveActualCount = async (ei) => {
    const val = actualCounts[ei.id];
    if (val === "" || val === undefined) return;
    await onUpdateActualCount(ei.id, parseInt(val, 10) || 0);
    showToast("Count saved");
  };

  return (
    <div className="fade-in" style={{ maxWidth: 900, margin: "0 auto", padding: "48px 24px 100px" }}>
      <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Events</button>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, flexWrap: "wrap", gap: 16 }}>
        <div>
          <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 26, color: BRAND.black, fontWeight: 800 }}>{event.name}</h1>
          <p style={{ fontSize: 13, color: BRAND.grey }}>
            {event.status === "active" ? "🟢 Live" : "Closed"} {"·"} {totalSold} sold {"·"} R{totalRevenue.toFixed(2)} revenue
          </p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button className="icon-btn" title="Refresh" onClick={refresh} style={{ border: `1px solid ${BRAND.greyLight}` }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>
          </button>
          {event.status === "active" && (
            <button className="ll-btn ll-btn-outline ll-btn-sm" onClick={() => { if (confirm(`End "${event.name}"? You'll still be able to review the summary and count actuals afterward.`)) onEnd(event.id); }}>End Event</button>
          )}
        </div>
      </div>

      <div style={{ marginTop: 24 }}>
        {rows.map(r => (
          <div key={r.id} className="admin-row" style={{ flexWrap: "wrap" }}>
            <div style={{ width: 40, height: 40, borderRadius: 6, overflow: "hidden", flexShrink: 0, background: BRAND.offWhite }}>
              {r.stall_items?.image && <img src={r.stall_items.image} alt={r.stall_items?.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />}
            </div>
            <div style={{ flex: 1, minWidth: 120 }}>
              <div style={{ fontWeight: 700, color: BRAND.black, fontSize: 14 }}>{r.stall_items?.name || "(deleted item)"}</div>
              <div style={{ fontSize: 12, color: BRAND.grey }}>{r.stall_items?.price}</div>
            </div>
            <div style={{ display: "flex", gap: 16, fontSize: 12, color: BRAND.grey, flexShrink: 0 }}>
              <div style={{ textAlign: "center" }}><div style={{ fontWeight: 800, color: BRAND.black, fontSize: 15 }}>{r.opening_stock}</div>Brought</div>
              <div style={{ textAlign: "center" }}><div style={{ fontWeight: 800, color: BRAND.purple, fontSize: 15 }}>{r.sold}</div>Sold</div>
              <div style={{ textAlign: "center" }}><div style={{ fontWeight: 800, color: r.remaining === 0 ? "#dc2626" : BRAND.black, fontSize: 15 }}>{r.remaining}</div>Expected Left</div>
              {event.status === "closed" && (
                <div style={{ textAlign: "center" }}>
                  <input
                    type="number" min="0" className="ll-input"
                    style={{ width: 60, padding: "6px 4px", textAlign: "center", fontSize: 13 }}
                    value={actualCounts[r.id] ?? ""}
                    onChange={e => setActualCounts(c => ({ ...c, [r.id]: e.target.value }))}
                    onBlur={() => saveActualCount(r)}
                  />
                  <div>Actual</div>
                </div>
              )}
              {event.status === "closed" && actualCounts[r.id] !== "" && actualCounts[r.id] !== undefined && (
                (() => {
                  const diff = (parseInt(actualCounts[r.id], 10) || 0) - r.remaining;
                  return <div style={{ textAlign: "center" }}><div style={{ fontWeight: 800, color: diff === 0 ? "#16a34a" : "#dc2626", fontSize: 15 }}>{diff > 0 ? `+${diff}` : diff}</div>Diff</div>;
                })()
              )}
            </div>
          </div>
        ))}
      </div>

      {event.status === "active" && (
        <div style={{ marginTop: 32 }}>
          <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 16, fontWeight: 800, color: BRAND.black, marginBottom: 12 }}>Recent Sales</h3>
          {summary.sales.length === 0 && <p style={{ color: BRAND.grey, fontSize: 14 }}>No sales logged yet — scan an item's QR code once it sells.</p>}
          {summary.sales.slice(0, 20).map(sale => {
            const item = summary.eventItems.find(ei => ei.stall_item_id === sale.stall_item_id)?.stall_items;
            return (
              <div key={sale.id} className="admin-row">
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 700, color: BRAND.black, fontSize: 13 }}>{item?.name || "(deleted item)"}</div>
                  <div style={{ fontSize: 11, color: BRAND.grey }}>{new Date(sale.sold_at).toLocaleTimeString("en-ZA", { hour: "2-digit", minute: "2-digit" })} {"·"} qty {sale.quantity}</div>
                </div>
                {sale.reference_code && (
                  <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: BRAND.tealDark, background: BRAND.tealLight, padding: "4px 10px", borderRadius: 100, flexShrink: 0 }}>Ref {sale.reference_code}</div>
                )}
                <button className="icon-btn" style={{ color: "#dc2626" }} title="Undo this sale" onClick={() => handleUndo(sale)}>{Icons.trash}</button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function AdminSalePage({ sale, sales, onBack, onNavigateNew, onNavigateEdit, onEnd }) {
  const pastSales = sales.filter(s => s.id !== sale?.id);
  const fmtDate = (d) => d ? new Date(d).toLocaleDateString("en-ZA", { day: "numeric", month: "short", year: "numeric" }) : "—";

  return (
    <div className="fade-in" style={{ maxWidth: 900, margin: "0 auto", padding: "48px 24px" }}>
      <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Admin</button>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24, flexWrap: "wrap", gap: 16 }}>
        <div>
          <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 28, color: BRAND.black, fontWeight: 800 }}>Sale</h1>
          <p style={{ fontSize: 13, color: BRAND.grey }}>A site-wide % discount on chosen Stall Price List items.</p>
        </div>
        {!sale && (
          <button className="ll-btn ll-btn-primary ll-btn-sm" onClick={onNavigateNew}>{Icons.plus} Start New Sale</button>
        )}
      </div>

      {sale && (
        <div style={{ background: `linear-gradient(115deg, ${BRAND.purple}, ${BRAND.teal})`, borderRadius: 14, padding: 24, marginBottom: 32, color: BRAND.white, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 16 }}>
          <div>
            <div style={{ fontSize: 11, letterSpacing: 2, textTransform: "uppercase", fontWeight: 700, opacity: 0.85, marginBottom: 6 }}>{"🔥 Live Now"}</div>
            <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 20, fontWeight: 800 }}>{sale.name} — {sale.discount_percent}% off</div>
            <div style={{ fontSize: 12, opacity: 0.85, marginTop: 4 }}>{sale.sale_items?.length || 0} item{sale.sale_items?.length !== 1 ? "s" : ""} {"·"} started {fmtDate(sale.started_at)}</div>
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="ll-btn ll-btn-sm" style={{ background: "rgba(255,255,255,0.2)", color: BRAND.white }} onClick={() => onNavigateEdit(sale)}>Edit</button>
            <button className="ll-btn ll-btn-sm" style={{ background: BRAND.white, color: BRAND.purple }} onClick={() => { if (confirm(`End the "${sale.name}" sale?`)) onEnd(sale.id); }}>End Sale</button>
          </div>
        </div>
      )}

      {!sale && pastSales.length === 0 && <p style={{ color: BRAND.grey, fontSize: 15, textAlign: "center", padding: 48 }}>No sales yet. Start one to show a banner on your homepage and a dedicated sale page.</p>}
      {pastSales.map(s => (
        <div key={s.id} className="admin-row">
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 700, color: BRAND.black, fontSize: 14 }}>{s.name} — {s.discount_percent}% off</div>
            <div style={{ fontSize: 12, color: BRAND.grey }}>{fmtDate(s.started_at)}{s.ended_at ? ` – ${fmtDate(s.ended_at)}` : ""} {"·"} {s.sale_items?.length || 0} item{s.sale_items?.length !== 1 ? "s" : ""}</div>
          </div>
          <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", padding: "4px 10px", borderRadius: 100, background: BRAND.offWhite, color: BRAND.grey }}>{s.status}</span>
        </div>
      ))}
    </div>
  );
}

function AdminSaleFormPage({ sale, stallItems, onCancel, showToast, onSave }) {
  const [name, setName] = useState(sale?.name || "");
  const [discountPercent, setDiscountPercent] = useState(sale?.discount_percent ?? 20);
  const [selected, setSelected] = useState(() => new Set((sale?.sale_items || []).map(si => si.stall_item_id)));

  const toggle = (id) => setSelected(prev => {
    const next = new Set(prev);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });

  const grouped = stallItems.reduce((acc, it) => {
    const key = titleCaseCategory(it.category) || "Other";
    (acc[key] = acc[key] || []).push(it);
    return acc;
  }, {});

  const handleSave = () => {
    if (!name.trim()) { showToast("Enter a sale name"); return; }
    if (selected.size === 0) { showToast("Pick at least one item"); return; }
    onSave({ id: sale?.id, name: name.trim(), discountPercent: Number(discountPercent) || 0, stallItemIds: [...selected] });
  };

  return (
    <div className="fade-in" style={{ maxWidth: 640, margin: "0 auto", padding: "48px 24px 100px" }}>
      <button onClick={onCancel} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Sale</button>
      <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 26, color: BRAND.black, fontWeight: 800, marginBottom: 8 }}>{sale ? "Edit Sale" : "Start New Sale"}</h1>
      <p style={{ fontSize: 13, color: BRAND.grey, marginBottom: 24 }}>Name it, set the discount, and pick which items are included. Stock shown is a live guide only.</p>

      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 12, marginBottom: 28 }}>
        <div>
          <label className="ll-label">Sale Name *</label>
          <input className="ll-input" value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Winter Clearance" />
        </div>
        <div>
          <label className="ll-label">Discount %</label>
          <input className="ll-input" type="number" min="0" max="100" value={discountPercent} onChange={e => setDiscountPercent(e.target.value)} />
        </div>
      </div>

      {stallItems.length === 0 && <p style={{ color: BRAND.grey, fontSize: 14 }}>Add items to your Stall Price List first.</p>}
      {Object.entries(grouped).sort(([a], [b]) => a.localeCompare(b)).map(([cat, catItems]) => (
        <div key={cat} style={{ marginBottom: 20 }}>
          <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 13, fontWeight: 800, letterSpacing: 1, textTransform: "uppercase", color: BRAND.purple, marginBottom: 10 }}>{cat}</h3>
          {catItems.map(item => {
            const checked = selected.has(item.id);
            return (
              <label key={item.id} style={{ display: "flex", alignItems: "center", gap: 14, padding: "10px 14px", background: checked ? BRAND.purpleLight : BRAND.white, borderRadius: 8, border: `1px solid ${checked ? BRAND.purple : BRAND.greyLight}`, marginBottom: 8, cursor: "pointer" }}>
                <input type="checkbox" checked={checked} onChange={() => toggle(item.id)} style={{ width: 18, height: 18, accentColor: BRAND.purple }} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontWeight: 700, fontSize: 14, color: BRAND.black }}>{item.name}</div>
                  <div style={{ fontSize: 12, color: BRAND.grey }}>{item.price} {"·"} Stock: {Math.max(0, item.stock ?? 0)}</div>
                </div>
              </label>
            );
          })}
        </div>
      ))}

      <div style={{ display: "flex", gap: 12, marginTop: 24 }}>
        <button className="ll-btn ll-btn-primary" style={{ flex: 1, justifyContent: "center" }} onClick={handleSave}>Save Sale</button>
        <button className="ll-btn ll-btn-outline" onClick={onCancel}>Cancel</button>
      </div>
    </div>
  );
}

function AdminStallLabelsPage({ stallItems, onBack }) {
  const [qrs, setQrs] = useState({});

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const QRCode = (await import("qrcode")).default;
      const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || "https://laskalegacy.co.za";
      const entries = await Promise.all(stallItems.map(async (item) => {
        const url = `${siteUrl}/stall-scan/${item.id}`;
        const dataUrl = await QRCode.toDataURL(url, { width: 240, margin: 1 });
        return [item.id, dataUrl];
      }));
      if (!cancelled) setQrs(Object.fromEntries(entries));
    })();
    return () => { cancelled = true; };
  }, [stallItems]);

  return (
    <div className="stall-labels-print" style={{ maxWidth: 1000, margin: "0 auto", padding: "48px 24px 100px" }}>
      <style>{`
        @media print {
          body * { visibility: hidden; }
          .stall-labels-print, .stall-labels-print * { visibility: visible; }
          .stall-labels-print { position: absolute; top: 0; left: 0; width: 100%; padding: 20px !important; margin: 0 !important; }
          .stall-labels-print .no-print { display: none !important; }
        }
        .stall-label-card { break-inside: avoid; }
      `}</style>
      <div className="no-print" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24, flexWrap: "wrap", gap: 16 }}>
        <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase" }}>{Icons.back} Back to Price List</button>
        <button className="ll-btn ll-btn-primary ll-btn-sm" onClick={() => window.print()}>{"🖨️"} Print</button>
      </div>
      <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 24, color: BRAND.black, fontWeight: 800, marginBottom: 8 }}>Stall Item QR Labels</h1>
      <p className="no-print" style={{ fontSize: 13, color: BRAND.grey, marginBottom: 24 }}>Print and laminate — each code is permanent, so you only need to print these once. Stick one on or near each physical item at the stall.</p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))", gap: 16 }}>
        {stallItems.map(item => (
          <div key={item.id} className="stall-label-card" style={{ border: `1px solid ${BRAND.greyLight}`, borderRadius: 10, padding: 14, textAlign: "center" }}>
            {qrs[item.id] ? (
              <img src={qrs[item.id]} alt={`QR for ${item.name}`} style={{ width: "100%", maxWidth: 160, margin: "0 auto 8px", display: "block" }} />
            ) : (
              <div style={{ width: "100%", aspectRatio: "1", background: BRAND.offWhite, borderRadius: 6, marginBottom: 8 }} />
            )}
            <div style={{ fontWeight: 700, fontSize: 13, color: BRAND.black }}>{item.name}</div>
            <div style={{ fontWeight: 800, fontSize: 13, color: BRAND.purple }}>{item.price}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function AdminGalleryPage({ gallery, setGallery, onBack, showToast }) {
  const [uploading, setUploading] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [captionText, setCaptionText] = useState("");

  const handleUpload = async (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    const imageFiles = files.filter(isImageFile);
    if (imageFiles.length === 0) {
      showToast("No image files selected (use JPG, PNG, WebP, etc.)");
      e.target.value = "";
      return;
    }
    setUploading(true);
    try {
      const urls = await uploadImageBatch("gallery", imageFiles);
      const newItems = urls.map((url, i) => ({ src: url, caption: "", sort_order: gallery.length + i }));
      const saved = await db.addGalleryItems(newItems);
      setGallery([...gallery, ...saved]);
      showToast(`${saved.length} image${saved.length > 1 ? "s" : ""} added`);
    } catch (err) {
      console.error(err);
      const msg = err?.message || err?.error_description || "Upload failed";
      showToast(typeof msg === "string" ? msg : "Could not upload to gallery.");
    }
    setUploading(false);
    e.target.value = "";
  };

  const handleDelete = async (item) => {
    await deleteImage("gallery", item.src);
    await db.deleteGalleryItem(item.id);
    setGallery(gallery.filter(g => g.id !== item.id));
    showToast("Image removed");
  };

  const handleSaveCaption = async (id) => {
    await db.updateGalleryItem(id, { caption: captionText });
    setGallery(gallery.map(g => g.id === id ? { ...g, caption: captionText } : g));
    setEditingId(null);
    showToast("Caption updated");
  };

  const moveItem = async (from, to) => {
    if (to < 0 || to >= gallery.length) return;
    const items = [...gallery];
    const [moved] = items.splice(from, 1);
    items.splice(to, 0, moved);
    setGallery(items);
    await db.reorderGallery(items);
  };

  return (
    <div className="fade-in" style={{ maxWidth: 900, margin: "0 auto", padding: "48px 24px" }}>
      <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Admin</button>
      
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 32, flexWrap: "wrap", gap: 16 }}>
        <div>
          <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 28, color: BRAND.black, fontWeight: 800 }}>Gallery</h1>
          <p style={{ fontSize: 13, color: BRAND.grey }}>{gallery.length} image{gallery.length !== 1 ? "s" : ""} {"\u00B7"} Shown on the homepage</p>
        </div>
      </div>

      {/* Upload area */}
      <label style={{
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        padding: "32px 20px", border: `2px dashed ${BRAND.greyLight}`, borderRadius: 10, cursor: "pointer",
        background: uploading ? BRAND.offWhite : BRAND.white, transition: "all 0.2s", marginBottom: 32,
      }}
        onMouseEnter={e => { e.currentTarget.style.borderColor = BRAND.teal; e.currentTarget.style.background = BRAND.tealLight; }}
        onMouseLeave={e => { e.currentTarget.style.borderColor = BRAND.greyLight; e.currentTarget.style.background = BRAND.white; }}
      >
        <input type="file" accept="image/*" multiple onChange={handleUpload} style={{ display: "none" }} />
        <div style={{ color: BRAND.teal, marginBottom: 8 }}>
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
        </div>
        <div style={{ fontSize: 14, fontWeight: 700, color: BRAND.black }}>
          {uploading ? "Uploading\u2026" : "Click to add gallery images"}
        </div>
        <div style={{ fontSize: 12, color: BRAND.grey, marginTop: 4 }}>Select multiple photos {"\u2014"} JPG, PNG, WebP</div>
      </label>

      {/* Gallery grid */}
      {gallery.length === 0 && <p style={{ color: BRAND.grey, fontSize: 15, textAlign: "center", padding: 32 }}>No gallery images yet. Upload some photos above to show them on your homepage.</p>}
      
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: 16 }}>
        {gallery.map((item, i) => (
          <div key={item.id} style={{ position: "relative", borderRadius: 10, overflow: "hidden", background: BRAND.offWhite, border: `1px solid ${BRAND.greyLight}` }}>
            <div style={{ aspectRatio: "1", overflow: "hidden" }}>
              <img src={item.src} alt={item.caption || "Gallery"} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
            </div>
            
            {/* Caption area */}
            <div style={{ padding: "10px 12px" }}>
              {editingId === item.id ? (
                <div style={{ display: "flex", gap: 6 }}>
                  <input className="ll-input" value={captionText} onChange={e => setCaptionText(e.target.value)} placeholder="Add a caption..." style={{ padding: "6px 10px", fontSize: 12 }}
                    onKeyDown={e => { if (e.key === "Enter") handleSaveCaption(item.id); }} autoFocus />
                  <button className="ll-btn ll-btn-primary" style={{ padding: "6px 12px", fontSize: 11, minWidth: "auto" }} onClick={() => handleSaveCaption(item.id)}>Save</button>
                </div>
              ) : (
                <div onClick={() => { setEditingId(item.id); setCaptionText(item.caption || ""); }} style={{ cursor: "pointer", minHeight: 20 }}>
                  {item.caption ? (
                    <p style={{ fontSize: 12, color: BRAND.black, fontWeight: 500, margin: 0 }}>{item.caption}</p>
                  ) : (
                    <p style={{ fontSize: 12, color: "#ccc", fontStyle: "italic", margin: 0 }}>Click to add caption...</p>
                  )}
                </div>
              )}
            </div>

            {/* Controls */}
            <div style={{ display: "flex", justifyContent: "space-between", padding: "0 8px 8px", gap: 4 }}>
              <div style={{ display: "flex", gap: 4 }}>
                {i > 0 && (
                  <button className="icon-btn" onClick={() => moveItem(i, i - 1)} title="Move left" style={{ fontSize: 13, padding: 4 }}>{"\u2190"}</button>
                )}
                {i < gallery.length - 1 && (
                  <button className="icon-btn" onClick={() => moveItem(i, i + 1)} title="Move right" style={{ fontSize: 13, padding: 4 }}>{"\u2192"}</button>
                )}
              </div>
              <button className="icon-btn" style={{ color: "#dc2626" }} onClick={() => { if (confirm("Remove this image?")) handleDelete(item); }}>{Icons.trash}</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── Public Sale Page ───
function SalePage({ sale, onBuyNow }) {
  if (!sale) {
    return (
      <div className="fade-in" style={{ maxWidth: 600, margin: "0 auto", padding: "80px 24px", textAlign: "center" }}>
        <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 26, color: BRAND.black, fontWeight: 800, marginBottom: 12 }}>No Sale Running Right Now</h1>
        <p style={{ fontSize: 14, color: BRAND.grey }}>Check back soon — we run these often!</p>
      </div>
    );
  }

  const items = (sale.sale_items || []).map(si => toSaleProduct(si.stall_items, sale.discount_percent));

  return (
    <div className="fade-in">
      <section style={{ position: "relative", overflow: "hidden", padding: "80px 24px 60px", textAlign: "center", background: `linear-gradient(125deg, ${BRAND.black} 0%, ${BRAND.purple} 55%, ${BRAND.teal} 100%)` }}>
        <div style={{ position: "absolute", inset: 0, opacity: 0.18, background: "repeating-linear-gradient(-45deg, rgba(255,255,255,0.6) 0 2px, transparent 2px 30px)" }} />
        <div style={{ position: "relative", maxWidth: 720, margin: "0 auto" }}>
          <div style={{ display: "inline-block", background: BRAND.white, color: BRAND.purple, fontFamily: "'Montserrat', sans-serif", fontWeight: 900, fontSize: "clamp(22px, 5vw, 36px)", padding: "10px 28px", borderRadius: 100, marginBottom: 20, transform: "rotate(-2deg)", boxShadow: "0 10px 26px rgba(0,0,0,0.3)" }}>
            🔥 {sale.discount_percent}% OFF
          </div>
          <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "clamp(26px, 5vw, 44px)", color: BRAND.white, fontWeight: 900, marginBottom: 16, letterSpacing: -0.5 }}>
            {sale.name}
          </h1>
          <p style={{ fontSize: 15, color: "rgba(255,255,255,0.9)", fontWeight: 700, maxWidth: 460, margin: "0 auto" }}>
            Only applicable to current stock on hand. While stocks last!
          </p>
        </div>
      </section>

      <div style={{ maxWidth: 1200, margin: "0 auto", padding: "48px 24px" }}>
        {items.length === 0 && <p style={{ textAlign: "center", color: BRAND.grey, padding: 48 }}>No items in this sale yet.</p>}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 24 }}>
          {items.map((p) => {
            const soldOut = p.stock <= 0;
            const lowStock = !soldOut && p.stock <= 3;
            return (
              <div key={p.id} className="product-card" style={{ opacity: soldOut ? 0.6 : 1 }}>
                <div style={{ position: "relative" }}>
                  <ProductImage name={p.name} category={p.category} images={p.images} />
                  <span style={{ position: "absolute", top: 12, left: 12, fontSize: 11, fontWeight: 800, letterSpacing: 1, textTransform: "uppercase", background: BRAND.purple, color: BRAND.white, padding: "5px 10px", borderRadius: 100 }}>
                    -{p.discountPercent}% OFF
                  </span>
                  {soldOut && (
                    <div style={{ position: "absolute", inset: 0, background: "rgba(255,255,255,0.75)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      <span style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1.5, textTransform: "uppercase", color: "#dc2626", background: BRAND.white, padding: "6px 12px", borderRadius: 100, boxShadow: "0 2px 8px rgba(0,0,0,0.15)" }}>Sold Out</span>
                    </div>
                  )}
                </div>
                <div style={{ padding: "20px 20px 24px" }}>
                  <div style={{ fontSize: 10, letterSpacing: 2, textTransform: "uppercase", color: BRAND.teal, marginBottom: 6, fontWeight: 700 }}>{titleCaseCategory(p.category)}</div>
                  <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 17, color: BRAND.black, fontWeight: 700, marginBottom: 8 }}>{p.name}</h3>
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 4 }}>
                    <span style={{ fontSize: 14, color: BRAND.grey, textDecoration: "line-through" }}>{p.originalPrice}</span>
                    <span style={{ fontSize: 20, fontWeight: 800, color: BRAND.purple }}>{p.price}</span>
                  </div>
                  {lowStock && <div style={{ fontSize: 12, color: "#dc2626", fontWeight: 700, marginBottom: 10 }}>Only {p.stock} left!</div>}
                  <button
                    className="ll-btn ll-btn-primary"
                    style={{ width: "100%", justifyContent: "center", marginTop: 10, opacity: soldOut ? 0.5 : 1, cursor: soldOut ? "not-allowed" : "pointer" }}
                    disabled={soldOut}
                    onClick={() => !soldOut && onBuyNow(p.stallItemId)}
                  >
                    {soldOut ? "Sold Out" : "Buy Now"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div style={{ textAlign: "center", padding: "0 24px 60px", fontSize: 13, color: BRAND.grey }}>
        Only applicable to current stock on hand. While stocks last.
      </div>
    </div>
  );
}

// ─── Public Order Form ───
function OrderFormPage({ products, saleProducts = [], preselectSaleItemId, onPreselectHandled, onSubmit }) {
  const [client, setClient] = useState({ name: "", email: "", phone: "", address: "", city: "", province: "", postalCode: "" });
  const [items, setItems] = useState([]);
  const [courier, setCourier] = useState("standard");
  const [notes, setNotes] = useState("");
  const [errors, setErrors] = useState({});
  const setC = (k, v) => setClient(c => ({ ...c, [k]: v }));
  const allSelectable = [...products, ...saleProducts];

  const toggleProduct = (p) => {
    const exists = items.find(it => it.productId === p.id);
    if (exists) setItems(items.filter(it => it.productId !== p.id));
    else setItems([...items, { productId: p.id, name: p.name, price: p.price, qty: 1, size: "", styleIndex: null, styleLabel: "" }]);
  };

  const preselectHandledRef = useRef(null);
  useEffect(() => {
    if (!preselectSaleItemId || preselectHandledRef.current === preselectSaleItemId) return;
    preselectHandledRef.current = preselectSaleItemId;
    const match = saleProducts.find(sp => sp.stallItemId === preselectSaleItemId);
    if (match) {
      setItems(prev => prev.find(it => it.productId === match.id) ? prev : [...prev, { productId: match.id, name: match.name, price: match.price, qty: 1, size: "", styleIndex: null, styleLabel: "" }]);
    }
    onPreselectHandled?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preselectSaleItemId]);

  const setQty = (pid, qty) => setItems(items.map(it => {
    if (it.productId !== pid) return it;
    const saleMatch = saleProducts.find(sp => sp.id === pid);
    const q = Math.max(1, qty);
    return { ...it, qty: saleMatch ? Math.min(q, Math.max(1, saleMatch.stock)) : q };
  }));
  const setItemOption = (pid, patch) => setItems(items.map(it => it.productId === pid ? { ...it, ...patch } : it));
  const total = items.reduce((s, it) => s + parsePrice(it.price) * it.qty, 0);
  const courierFee = courier === "express" ? 250 : courier === "standard" ? 150 : 0;

  const validate = () => {
    const e = {};
    if (!client.name.trim()) e.name = true;
    if (!client.email.trim() || !client.email.includes("@")) e.email = true;
    if (!client.phone.trim()) e.phone = true;
    if (courier !== "collect" && !client.address.trim()) e.address = true;
    if (items.length === 0) e.items = true;
    items.forEach(it => {
      const p = allSelectable.find(x => x.id === it.productId);
      if (!p) return;
      if (p.isSaleItem && (p.stock <= 0 || it.qty > p.stock)) e.saleStock = true;
      if (!productNeedsOrderOptions(p)) return;
      const sizes = getProductSizes(p);
      const styles = getProductStyles(p);
      if (sizes.length && !it.size) e.itemOptions = true;
      if (styles.length && (it.styleIndex == null || it.styleIndex < 0)) e.itemOptions = true;
    });
    setErrors(e); return Object.keys(e).length === 0;
  };

  return (
    <div className="fade-in" style={{ maxWidth: 760, margin: "0 auto", padding: "48px 24px 80px" }}>
      <div style={{ textAlign: "center", marginBottom: 40 }}>
        <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 32, color: BRAND.black, fontWeight: 800, marginBottom: 8 }}>Place an Order</h1>
        <p style={{ fontSize: 14, color: BRAND.grey }}>Fill in your details, pick your products, and we'll send you an invoice.</p>
      </div>

      {/* Client details */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 16, fontWeight: 700, color: BRAND.black, marginBottom: 16 }}>Your Details</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div><label className="ll-label">Full Name *</label><input className="ll-input" value={client.name} onChange={e => setC("name", e.target.value)} style={errors.name ? { borderColor: "#dc2626" } : {}} /></div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <div><label className="ll-label">Email *</label><input className="ll-input" type="email" value={client.email} onChange={e => setC("email", e.target.value)} style={errors.email ? { borderColor: "#dc2626" } : {}} /></div>
            <div><label className="ll-label">Phone *</label><input className="ll-input" type="tel" value={client.phone} onChange={e => setC("phone", e.target.value)} style={errors.phone ? { borderColor: "#dc2626" } : {}} /></div>
          </div>
          <div><label className="ll-label">Street Address {courier !== "collect" ? "*" : ""}</label><input className="ll-input" value={client.address} onChange={e => setC("address", e.target.value)} style={errors.address ? { borderColor: "#dc2626" } : {}} /></div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12 }}>
            <div><label className="ll-label">City</label><input className="ll-input" value={client.city} onChange={e => setC("city", e.target.value)} /></div>
            <div><label className="ll-label">Province</label><input className="ll-input" value={client.province} onChange={e => setC("province", e.target.value)} /></div>
            <div><label className="ll-label">Postal Code</label><input className="ll-input" value={client.postalCode} onChange={e => setC("postalCode", e.target.value)} /></div>
          </div>
        </div>
      </div>

      {/* On Sale */}
      {saleProducts.length > 0 && (
        <div style={{ marginBottom: 32 }}>
          <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 16, fontWeight: 700, color: BRAND.purple, marginBottom: 4 }}>🔥 On Sale — While Stocks Last</h3>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 12 }}>
            {saleProducts.map(p => {
              const sel = items.find(it => it.productId === p.id);
              const soldOut = p.stock <= 0;
              return (
                <div
                  key={p.id}
                  onClick={() => !soldOut && !sel && toggleProduct(p)}
                  style={{
                    display: "flex", alignItems: "center", gap: 14, padding: "12px 16px", borderRadius: 10,
                    border: sel ? `2px solid ${BRAND.purple}` : `1px solid ${BRAND.greyLight}`, background: sel ? BRAND.purpleLight : BRAND.white,
                    cursor: soldOut ? "not-allowed" : "pointer", opacity: soldOut ? 0.5 : 1, transition: "all 0.2s",
                  }}
                >
                  <div style={{ width: 22, height: 22, borderRadius: 4, border: sel ? `2px solid ${BRAND.purple}` : `2px solid ${BRAND.greyLight}`, background: sel ? BRAND.purple : BRAND.white, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    {sel && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={BRAND.white} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: 14, color: BRAND.black }}>{p.name}</div>
                    <div style={{ fontSize: 12, color: BRAND.grey }}>{titleCaseCategory(p.category)}</div>
                  </div>
                  {soldOut ? (
                    <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1.4, textTransform: "uppercase", background: "#dc2626", color: BRAND.white, padding: "5px 10px", borderRadius: 100, flexShrink: 0 }}>Sold Out</span>
                  ) : (
                    <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
                      <span style={{ fontSize: 13, color: BRAND.grey, textDecoration: "line-through" }}>{p.originalPrice}</span>
                      <span style={{ fontWeight: 800, color: BRAND.purple, fontSize: 14 }}>{p.price}</span>
                    </div>
                  )}
                  {sel && !soldOut && (
                    <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }} onClick={e => e.stopPropagation()}>
                      <button onClick={() => setQty(p.id, sel.qty - 1)} style={{ width: 28, height: 28, borderRadius: 6, border: `1px solid ${BRAND.greyLight}`, background: BRAND.white, cursor: "pointer", fontSize: 16, fontWeight: 700 }}>{"−"}</button>
                      <span style={{ width: 24, textAlign: "center", fontWeight: 700, fontSize: 14 }}>{sel.qty}</span>
                      <button onClick={() => setQty(p.id, sel.qty + 1)} style={{ width: 28, height: 28, borderRadius: 6, border: `1px solid ${BRAND.greyLight}`, background: BRAND.white, cursor: "pointer", fontSize: 16, fontWeight: 700 }}>+</button>
                      <button onClick={() => toggleProduct(p)} style={{ marginLeft: 4, background: "none", border: "none", cursor: "pointer", color: "#dc2626", fontSize: 16 }}>{"✕"}</button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Product selection */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 16, fontWeight: 700, color: BRAND.black, marginBottom: 4 }}>Select Products *</h3>
        {errors.items && <p style={{ fontSize: 12, color: "#dc2626", marginBottom: 8 }}>Please select at least one product</p>}
        {errors.itemOptions && <p style={{ fontSize: 12, color: "#dc2626", marginBottom: 8 }}>Please choose a size and style for each shirt with options</p>}
        {errors.saleStock && <p style={{ fontSize: 12, color: "#dc2626", marginBottom: 8 }}>One of your sale items is sold out or below the quantity you selected — please adjust.</p>}
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 12 }}>
          {products.map(p => {
            const sel = items.find(it => it.productId === p.id);
            const sizes = getProductSizes(p);
            const styles = getProductStyles(p);
            const showOptions = sel && productNeedsOrderOptions(p);
            return (
              <div key={p.id} style={{ display: "flex", flexDirection: "column", gap: 0 }}>
              <div onClick={() => !sel && toggleProduct(p)} style={{
                display: "flex", alignItems: "center", gap: 14, padding: "12px 16px", borderRadius: showOptions ? "10px 10px 0 0" : 10,
                border: sel ? `2px solid ${BRAND.teal}` : `1px solid ${BRAND.greyLight}`, background: sel ? BRAND.tealLight : BRAND.white,
                borderBottom: showOptions ? "none" : undefined,
                cursor: "pointer", transition: "all 0.2s",
              }}>
                <div style={{ width: 22, height: 22, borderRadius: 4, border: sel ? `2px solid ${BRAND.teal}` : `2px solid ${BRAND.greyLight}`, background: sel ? BRAND.teal : BRAND.white, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transition: "all 0.2s" }}>
                  {sel && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={BRAND.white} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, fontSize: 14, color: BRAND.black }}>{p.name}</div>
                  <div style={{ fontSize: 12, color: BRAND.grey }}>{CATEGORIES[p.category]?.label || titleCaseCategory(p.category)}</div>
                </div>
                <div style={{ fontWeight: 800, color: BRAND.purple, fontSize: 14, flexShrink: 0 }}>{p.price}</div>
                {sel && (
                  <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }} onClick={e => e.stopPropagation()}>
                    <button onClick={() => setQty(p.id, sel.qty - 1)} style={{ width: 28, height: 28, borderRadius: 6, border: `1px solid ${BRAND.greyLight}`, background: BRAND.white, cursor: "pointer", fontSize: 16, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>{"\u2212"}</button>
                    <span style={{ width: 24, textAlign: "center", fontWeight: 700, fontSize: 14 }}>{sel.qty}</span>
                    <button onClick={() => setQty(p.id, sel.qty + 1)} style={{ width: 28, height: 28, borderRadius: 6, border: `1px solid ${BRAND.greyLight}`, background: BRAND.white, cursor: "pointer", fontSize: 16, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>+</button>
                    <button onClick={() => toggleProduct(p)} style={{ marginLeft: 4, background: "none", border: "none", cursor: "pointer", color: "#dc2626", fontSize: 16 }}>{"\u2715"}</button>
                  </div>
                )}
              </div>
              {showOptions && (
                <div onClick={e => e.stopPropagation()} style={{
                  padding: "16px", borderRadius: "0 0 10px 10px",
                  border: `2px solid ${BRAND.teal}`, borderTop: `1px solid ${BRAND.greyLight}`,
                  background: BRAND.white,
                }}>
                  {sizes.length > 0 && (
                    <div style={{ marginBottom: styles.length > 0 ? 16 : 0 }}>
                      <div className="ll-label" style={{ marginBottom: 8 }}>Size *</div>
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                        {sizes.map(size => (
                          <button
                            key={size}
                            type="button"
                            onClick={() => setItemOption(p.id, { size })}
                            style={{
                              padding: "8px 16px", borderRadius: 6, border: sel.size === size ? `2px solid ${BRAND.teal}` : `1px solid ${BRAND.greyLight}`,
                              background: sel.size === size ? BRAND.tealLight : BRAND.white,
                              fontWeight: 700, fontSize: 13, cursor: "pointer", color: BRAND.black,
                            }}
                          >{size}</button>
                        ))}
                      </div>
                    </div>
                  )}
                  {styles.length > 0 && (
                    <div>
                      <div className="ll-label" style={{ marginBottom: 8 }}>Style *</div>
                      <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
                        {styles.map(style => (
                          <button
                            key={style.index}
                            type="button"
                            onClick={() => setItemOption(p.id, { styleIndex: style.index, styleLabel: style.label })}
                            style={{
                              width: 88, padding: 0, border: sel.styleIndex === style.index ? `2px solid ${BRAND.teal}` : `1px solid ${BRAND.greyLight}`,
                              borderRadius: 8, background: BRAND.white, cursor: "pointer", overflow: "hidden", textAlign: "left",
                            }}
                          >
                            <img src={style.image} alt={style.label} style={{ width: "100%", height: 72, objectFit: "cover", display: "block" }} />
                            <div style={{ padding: "6px 8px", fontSize: 11, fontWeight: 700, color: BRAND.black, lineHeight: 1.2 }}>{style.label}</div>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Courier */}
      <div style={{ marginBottom: 32 }}>
        <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 16, fontWeight: 700, color: BRAND.black, marginBottom: 12 }}>Delivery</h3>
        {[["standard", "Standard Courier", "R150", "3\u20135 business days"], ["express", "Express Courier", "R250", "1\u20132 business days"], ["collect", "Collect", "Free", "Arrange with us"]].map(([val, label, price, desc]) => (
          <label key={val} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderRadius: 10, border: courier === val ? `2px solid ${BRAND.teal}` : `1px solid ${BRAND.greyLight}`, background: courier === val ? BRAND.tealLight : BRAND.white, cursor: "pointer", marginBottom: 8, transition: "all 0.2s" }}>
            <input type="radio" name="courier" checked={courier === val} onChange={() => setCourier(val)} style={{ accentColor: BRAND.teal, width: 18, height: 18 }} />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, fontSize: 14, color: BRAND.black }}>{label}</div>
              <div style={{ fontSize: 12, color: BRAND.grey }}>{desc}</div>
            </div>
            <div style={{ fontWeight: 700, color: BRAND.purple, fontSize: 14 }}>{price}</div>
          </label>
        ))}
      </div>

      {/* Notes */}
      <div style={{ marginBottom: 32 }}>
        <label className="ll-label">Notes / Special Requests</label>
        <textarea className="ll-input" value={notes} onChange={e => setNotes(e.target.value)} placeholder="Custom colours, sizing notes, anything we should know..." />
      </div>

      {/* Summary */}
      {items.length > 0 && (
        <div style={{ background: BRAND.offWhite, borderRadius: 10, padding: 24, marginBottom: 32 }}>
          <h3 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 14, fontWeight: 700, color: BRAND.black, marginBottom: 12 }}>Order Summary</h3>
          {items.map(it => (
            <div key={it.productId} style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: BRAND.grey, marginBottom: 6 }}>
              <span>{formatOrderItemLabel(it)} {"\u00D7"} {it.qty}</span>
              <span style={{ fontWeight: 600, color: BRAND.black }}>{formatPrice(parsePrice(it.price) * it.qty)}</span>
            </div>
          ))}
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: BRAND.grey, marginBottom: 6 }}>
            <span>Delivery ({courier})</span><span style={{ fontWeight: 600, color: BRAND.black }}>{formatPrice(courierFee)}</span>
          </div>
          <div style={{ borderTop: `1px solid ${BRAND.greyLight}`, marginTop: 10, paddingTop: 10, display: "flex", justifyContent: "space-between", fontSize: 16, fontWeight: 800 }}>
            <span>Total</span><span style={{ color: BRAND.purple }}>{formatPrice(total + courierFee)}</span>
          </div>
        </div>
      )}

      <button className="ll-btn ll-btn-primary" style={{ width: "100%", justifyContent: "center", padding: "16px 28px" }} onClick={() => {
        if (validate()) onSubmit({ client, items, courier, courierFee, notes, total: total + courierFee });
      }}>Submit Order</button>
      <p style={{ fontSize: 12, color: BRAND.grey, textAlign: "center", marginTop: 12 }}>We'll review your order and send you an invoice via email or WhatsApp.</p>
    </div>
  );
}

// ─── Admin Order Detail + Invoice Generator ───
function OrderDetailPage({ order, onUpdate, onBack, showToast, logoWhite }) {
  const [items, setItems] = useState(order.items || []);
  const [courier, setCourier] = useState(order.courier || "standard");
  const [courierFee, setCourierFee] = useState(order.courierFee ?? 150);
  const [discount, setDiscount] = useState(order.discount || 0);
  const [notes, setNotes] = useState(order.notes || "");
  const [generating, setGenerating] = useState(false);

  const setItemField = (i, k, v) => setItems(prev => prev.map((it, idx) => idx === i ? { ...it, [k]: v } : it));
  const removeItem = (i) => setItems(prev => prev.filter((_, idx) => idx !== i));
  const addItem = () => setItems([...items, { productId: "", name: "Custom item", price: "R0", qty: 1 }]);

  const subtotal = items.reduce((s, it) => s + parsePrice(it.price) * it.qty, 0);
  const total = subtotal + courierFee - discount;

  const saveChanges = () => {
    onUpdate({ ...order, items, courier, courierFee, discount, notes, total });
    showToast("Changes saved");
  };

  const markInvoiced = () => {
    onUpdate({ ...order, items, courier, courierFee, discount, notes, total, status: "invoiced" });
    showToast("Marked as invoiced");
  };

  const generateInvoicePDF = async () => {
    setGenerating(true);
    try {
      const invoiceHTML = buildInvoiceHTML({ ...order, items, courier, courierFee, discount, notes, total, subtotal }, logoWhite);
      const w = window.open("", "_blank", "width=800,height=1000");
      w.document.write(invoiceHTML);
      w.document.close();
      setTimeout(() => { w.print(); setGenerating(false); markInvoiced(); }, 600);
    } catch (err) {
      console.error(err); showToast("Error generating invoice"); setGenerating(false);
    }
  };

  return (
    <div className="fade-in" style={{ maxWidth: 800, margin: "0 auto", padding: "48px 24px 80px" }}>
      <button onClick={onBack} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back to Orders</button>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", flexWrap: "wrap", gap: 16, marginBottom: 32 }}>
        <div>
          <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 28, color: BRAND.black, fontWeight: 800 }}>Order {order.invoiceNumber}</h1>
          <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", padding: "4px 10px", borderRadius: 100, background: order.status === "new" ? BRAND.tealLight : order.status === "invoiced" ? BRAND.purpleLight : BRAND.offWhite, color: order.status === "new" ? BRAND.tealDark : order.status === "invoiced" ? BRAND.purple : BRAND.grey }}>{order.status}</span>
        </div>
        <div style={{ fontSize: 13, color: BRAND.grey }}>{new Date(order.date).toLocaleDateString("en-ZA", { day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" })}</div>
      </div>

      {/* Client info */}
      <div style={{ background: BRAND.offWhite, borderRadius: 10, padding: 20, marginBottom: 24 }}>
        <h3 style={{ fontSize: 11, fontWeight: 700, letterSpacing: 2, textTransform: "uppercase", color: BRAND.grey, marginBottom: 10 }}>Client</h3>
        <div style={{ fontSize: 15, fontWeight: 700, color: BRAND.black }}>{order.client.name}</div>
        <div style={{ fontSize: 13, color: BRAND.grey, marginTop: 4 }}>{order.client.email} {"\u00B7"} {order.client.phone}</div>
        {order.client.address && <div style={{ fontSize: 13, color: BRAND.grey, marginTop: 2 }}>{order.client.address}{order.client.city ? `, ${order.client.city}` : ""}{order.client.province ? `, ${order.client.province}` : ""} {order.client.postalCode}</div>}
      </div>

      {/* Editable line items */}
      <div style={{ marginBottom: 24 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <h3 style={{ fontSize: 11, fontWeight: 700, letterSpacing: 2, textTransform: "uppercase", color: BRAND.grey }}>Line Items</h3>
          <button className="ll-btn ll-btn-primary ll-btn-sm" onClick={addItem}>{Icons.plus} Add Item</button>
        </div>
        {items.map((it, i) => (
          <div key={i} style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 8, flexWrap: "wrap" }}>
            <input className="ll-input" value={it.name} onChange={e => setItemField(i, "name", e.target.value)} style={{ flex: 2, minWidth: 160, padding: "8px 12px", fontSize: 13 }} />
            <input className="ll-input" value={it.price} onChange={e => setItemField(i, "price", e.target.value)} placeholder="R0" style={{ width: 100, padding: "8px 12px", fontSize: 13 }} />
            <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <span style={{ fontSize: 12, color: BRAND.grey }}>{"\u00D7"}</span>
              <input className="ll-input" type="number" min="1" value={it.qty} onChange={e => setItemField(i, "qty", parseInt(e.target.value) || 1)} style={{ width: 60, padding: "8px 10px", fontSize: 13, textAlign: "center" }} />
            </div>
            <div style={{ fontSize: 13, fontWeight: 700, color: BRAND.black, width: 80, textAlign: "right" }}>{formatPrice(parsePrice(it.price) * it.qty)}</div>
            <button className="icon-btn" style={{ color: "#dc2626" }} onClick={() => removeItem(i)}>{Icons.trash}</button>
          </div>
        ))}
      </div>

      {/* Courier + Discount */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 24 }}>
        <div>
          <label className="ll-label">Courier</label>
          <select className="ll-input" value={courier} onChange={e => { setCourier(e.target.value); setCourierFee(e.target.value === "express" ? 250 : e.target.value === "standard" ? 150 : 0); }} style={{ padding: "8px 12px", fontSize: 13 }}>
            <option value="standard">Standard (R150)</option>
            <option value="express">Express (R250)</option>
            <option value="collect">Collect (Free)</option>
          </select>
        </div>
        <div>
          <label className="ll-label">Courier Fee</label>
          <input className="ll-input" type="number" value={courierFee} onChange={e => setCourierFee(parseFloat(e.target.value) || 0)} style={{ padding: "8px 12px", fontSize: 13 }} />
        </div>
        <div>
          <label className="ll-label">Discount</label>
          <input className="ll-input" type="number" value={discount} onChange={e => setDiscount(parseFloat(e.target.value) || 0)} style={{ padding: "8px 12px", fontSize: 13 }} />
        </div>
      </div>

      {/* Notes */}
      <div style={{ marginBottom: 24 }}>
        <label className="ll-label">Notes</label>
        <textarea className="ll-input" value={notes} onChange={e => setNotes(e.target.value)} style={{ minHeight: 80 }} />
      </div>

      {/* Totals */}
      <div style={{ background: BRAND.offWhite, borderRadius: 10, padding: 20, marginBottom: 32 }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: BRAND.grey, marginBottom: 6 }}><span>Subtotal</span><span style={{ fontWeight: 600, color: BRAND.black }}>{formatPrice(subtotal)}</span></div>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: BRAND.grey, marginBottom: 6 }}><span>Courier</span><span style={{ fontWeight: 600, color: BRAND.black }}>{formatPrice(courierFee)}</span></div>
        {discount > 0 && <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "#16a34a", marginBottom: 6 }}><span>Discount</span><span style={{ fontWeight: 600 }}>{"\u2212"}{formatPrice(discount)}</span></div>}
        <div style={{ borderTop: `1px solid ${BRAND.greyLight}`, marginTop: 8, paddingTop: 8, display: "flex", justifyContent: "space-between", fontSize: 18, fontWeight: 800 }}><span>Total</span><span style={{ color: BRAND.purple }}>{formatPrice(total)}</span></div>
      </div>

      {/* Action buttons */}
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
        <button className="ll-btn ll-btn-outline" onClick={saveChanges} style={{ flex: 1 }}>Save Changes</button>
        <button className="ll-btn ll-btn-primary" onClick={generateInvoicePDF} disabled={generating} style={{ flex: 1, opacity: generating ? 0.6 : 1 }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
          {generating ? "Generating..." : "Generate Invoice PDF"}
        </button>
      </div>
    </div>
  );
}

// ─── Invoice HTML builder ───
function buildInvoiceHTML(order, logoBase64) {
  const itemRows = order.items.map(it => `
    <tr>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;">${formatOrderItemLabel(it)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;text-align:center;">${it.qty}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;text-align:right;">${formatPrice(parsePrice(it.price))}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;text-align:right;font-weight:600;">${formatPrice(parsePrice(it.price) * it.qty)}</td>
    </tr>
  `).join("");

  const addr = [order.client.address, order.client.city, order.client.province, order.client.postalCode].filter(Boolean).join(", ");

  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Invoice ${order.invoiceNumber}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
  * { margin:0; padding:0; box-sizing:border-box; }
  body { font-family:'Inter',sans-serif; color:#000; background:#fff; }
  @media print { body { -webkit-print-color-adjust:exact; print-color-adjust:exact; } }
</style></head><body>
<div style="max-width:700px;margin:0 auto;padding:40px;">
  <!-- Header -->
  <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:40px;">
    <div style="display:flex;align-items:center;gap:14px;">
      <img src="${logoBase64}" style="height:48px;" />
      <div>
        <div style="font-family:'Montserrat',sans-serif;font-size:20px;font-weight:800;letter-spacing:1px;">LASKA LEGACY</div>
        <div style="font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#0097b2;font-weight:600;margin-top:2px;">Leather & Canvas</div>
      </div>
    </div>
    <div style="text-align:right;">
      <div style="font-family:'Montserrat',sans-serif;font-size:28px;font-weight:800;color:#0097b2;">INVOICE</div>
      <div style="font-size:13px;color:#6b7280;margin-top:4px;">${order.invoiceNumber}</div>
      <div style="font-size:12px;color:#6b7280;">${new Date(order.date).toLocaleDateString("en-ZA", { day: "numeric", month: "long", year: "numeric" })}</div>
    </div>
  </div>

  <!-- Bill To + From -->
  <div style="display:flex;gap:40px;margin-bottom:36px;">
    <div style="flex:1;">
      <div style="font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#6b7280;margin-bottom:8px;">Bill To</div>
      <div style="font-size:15px;font-weight:700;">${order.client.name}</div>
      <div style="font-size:13px;color:#6b7280;margin-top:4px;">${order.client.email}</div>
      <div style="font-size:13px;color:#6b7280;">${order.client.phone}</div>
      ${addr ? `<div style="font-size:13px;color:#6b7280;margin-top:4px;">${addr}</div>` : ""}
    </div>
    <div style="flex:1;">
      <div style="font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#6b7280;margin-bottom:8px;">From</div>
      <div style="font-size:15px;font-weight:700;">Laska Legacy (Pty) Ltd</div>
      <div style="font-size:13px;color:#6b7280;margin-top:4px;">laskalegacypty@gmail.com</div>
      <div style="font-size:13px;color:#6b7280;">+27 72 585 8288</div>
    </div>
  </div>

  <!-- Items table -->
  <table style="width:100%;border-collapse:collapse;margin-bottom:24px;">
    <thead>
      <tr style="background:#000;">
        <th style="padding:10px 12px;text-align:left;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#fff;">Item</th>
        <th style="padding:10px 12px;text-align:center;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#fff;">Qty</th>
        <th style="padding:10px 12px;text-align:right;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#fff;">Unit Price</th>
        <th style="padding:10px 12px;text-align:right;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#fff;">Total</th>
      </tr>
    </thead>
    <tbody>${itemRows}</tbody>
  </table>

  <!-- Totals -->
  <div style="display:flex;justify-content:flex-end;">
    <div style="width:260px;">
      <div style="display:flex;justify-content:space-between;padding:6px 0;font-size:13px;color:#6b7280;"><span>Subtotal</span><span style="font-weight:600;color:#000;">${formatPrice(order.subtotal)}</span></div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;font-size:13px;color:#6b7280;"><span>Courier (${order.courier})</span><span style="font-weight:600;color:#000;">${formatPrice(order.courierFee)}</span></div>
      ${order.discount > 0 ? `<div style="display:flex;justify-content:space-between;padding:6px 0;font-size:13px;color:#16a34a;"><span>Discount</span><span style="font-weight:600;">\u2212${formatPrice(order.discount)}</span></div>` : ""}
      <div style="display:flex;justify-content:space-between;padding:12px 0 6px;font-size:18px;font-weight:800;border-top:2px solid #000;margin-top:8px;"><span>Total</span><span style="color:#5e17eb;">${formatPrice(order.total)}</span></div>
    </div>
  </div>

  ${order.notes ? `<div style="margin-top:28px;padding:16px;background:#f7f8fa;border-radius:8px;font-size:13px;color:#6b7280;"><strong style="color:#000;">Notes:</strong> ${order.notes}</div>` : ""}

  <!-- Footer -->
  <div style="margin-top:48px;padding-top:20px;border-top:1px solid #e5e7eb;text-align:center;">
    <div style="font-size:12px;color:#6b7280;">Thank you for your order!</div>
    <div style="font-size:11px;color:#0097b2;margin-top:4px;font-weight:600;">Laska Legacy {"\u00B7"} laskalegacypty@gmail.com {"\u00B7"} +27 72 585 8288</div>
    <div style="font-size:10px;color:#ccc;margin-top:8px;">@laska_legacy {"\u00B7"} @the_westerngames_rider</div>
  </div>
</div></body></html>`;
}

// ─── Blog Post Editor ───
function BlogEditPage({ post, onSave, onCancel, showToast }) {
  const [form, setForm] = useState({ ...post, images: post.images || [], videos: post.videos || [] });
  const [uploading, setUploading] = useState(false);
  const [newVideo, setNewVideo] = useState("");
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleCoverUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file || !isImageFile(file)) {
      showToast?.("Choose an image file (JPG, PNG, WebP, etc.)");
      e.target.value = "";
      return;
    }
    setUploading(true);
    try {
      const optimizedFile = await optimizeImageForUpload(file);
      const url = await uploadImage("blog", optimizedFile);
      set("coverImage", url);
      showToast?.("Cover image uploaded");
    } catch (err) {
      console.error("Cover upload error:", err);
      const msg = err?.message || err?.error_description || "Cover upload failed";
      showToast?.(typeof msg === "string" ? msg : "Could not upload cover image.");
    }
    setUploading(false);
    e.target.value = "";
  };

  const handleImagesUpload = async (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    const imageFiles = files.filter(isImageFile);
    if (imageFiles.length === 0) {
      showToast?.("No image files selected (use JPG, PNG, WebP, etc.)");
      e.target.value = "";
      return;
    }
    setUploading(true);
    try {
      const newImgs = await uploadImageBatch("blog", imageFiles);
      setForm(f => ({ ...f, images: [...(f.images || []), ...newImgs] }));
      showToast?.(newImgs.length === 1 ? "Image uploaded" : `${newImgs.length} images uploaded`);
    } catch (err) {
      console.error("Blog image upload error:", err);
      const msg = err?.message || err?.error_description || "Upload failed";
      showToast?.(typeof msg === "string" ? msg : "Could not upload blog images.");
    }
    setUploading(false);
    e.target.value = "";
  };

  const removeImage = (i) => setForm(f => ({ ...f, images: f.images.filter((_, idx) => idx !== i) }));
  const addVideo = () => {
    if (!newVideo.trim()) return;
    setForm(f => ({ ...f, videos: [...(f.videos || []), newVideo.trim()] }));
    setNewVideo("");
  };
  const removeVideo = (i) => setForm(f => ({ ...f, videos: f.videos.filter((_, idx) => idx !== i) }));

  return (
    <div className="fade-in" style={{ maxWidth: 720, margin: "0 auto", padding: "48px 24px 80px" }}>
      <button onClick={onCancel} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", cursor: "pointer", color: BRAND.grey, fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", marginBottom: 24 }}>{Icons.back} Back</button>
      <h1 style={{ fontFamily: "'Montserrat', sans-serif", fontSize: 28, color: BRAND.black, fontWeight: 800, marginBottom: 32 }}>{form.id ? "Edit Post" : "New Post"}</h1>

      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        {/* Title */}
        <div>
          <label className="ll-label">Title</label>
          <input className="ll-input" value={form.title} onChange={e => set("title", e.target.value)} placeholder="Give your post a title..." style={{ fontSize: 18, fontWeight: 700, fontFamily: "'Montserrat', sans-serif", padding: "14px 16px" }} />
        </div>

        {/* Excerpt */}
        <div>
          <label className="ll-label">Excerpt / Preview Text</label>
          <input className="ll-input" value={form.excerpt || ""} onChange={e => set("excerpt", e.target.value)} placeholder="Short summary shown on the blog listing..." />
        </div>

        {/* Cover Image */}
        <div>
          <label className="ll-label">Cover Image</label>
          {form.coverImage ? (
            <div style={{ position: "relative", borderRadius: 10, overflow: "hidden", marginBottom: 8, aspectRatio: "16/7", background: BRAND.offWhite }}>
              <img src={form.coverImage} alt="Cover" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
              <button onClick={() => set("coverImage", "")} style={{ position: "absolute", top: 8, right: 8, background: "rgba(220,38,38,0.9)", color: "#fff", border: "none", borderRadius: 6, padding: "4px 10px", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>Remove</button>
            </div>
          ) : (
            <label style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "24px", border: `2px dashed ${BRAND.greyLight}`, borderRadius: 8, cursor: "pointer", background: BRAND.white, transition: "all 0.2s" }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = BRAND.teal; e.currentTarget.style.background = BRAND.tealLight; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = BRAND.greyLight; e.currentTarget.style.background = BRAND.white; }}>
              <input type="file" accept="image/*" onChange={handleCoverUpload} style={{ display: "none" }} />
              <div style={{ fontSize: 13, fontWeight: 700, color: BRAND.black }}>{uploading ? "Uploading\u2026" : "Click to upload cover image"}</div>
              <div style={{ fontSize: 11, color: BRAND.grey, marginTop: 2 }}>Recommended: landscape, at least 1200px wide</div>
            </label>
          )}
        </div>

        {/* Body */}
        <div>
          <label className="ll-label">Post Content</label>
          <p style={{ fontSize: 11, color: BRAND.grey, marginBottom: 8 }}>Write your post. Use # or ## at the start of a line for headings. Blank lines create paragraph breaks.</p>
          <textarea className="ll-input" value={form.body || ""} onChange={e => set("body", e.target.value)} placeholder={"Start writing your post here...\n\n## A Subheading\n\nMore content here..."} style={{ minHeight: 280, fontFamily: "'Inter', sans-serif", fontSize: 14, lineHeight: 1.7 }} />
        </div>

        {/* Post Images */}
        <div>
          <label className="ll-label">Post Images</label>
          <p style={{ fontSize: 11, color: BRAND.grey, marginBottom: 8 }}>Additional photos displayed below the post content.</p>
          {form.images.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginBottom: 12 }}>
              {form.images.map((src, i) => (
                <div key={i} style={{ position: "relative", width: 90, height: 90, borderRadius: 8, overflow: "hidden", border: `1px solid ${BRAND.greyLight}` }}>
                  <img src={src} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                  <button onClick={() => removeImage(i)} style={{ position: "absolute", top: 2, right: 2, background: "rgba(220,38,38,0.9)", color: "#fff", border: "none", borderRadius: "50%", width: 20, height: 20, fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}>{"\u2715"}</button>
                </div>
              ))}
            </div>
          )}
          <label style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: "14px", border: `2px dashed ${BRAND.greyLight}`, borderRadius: 8, cursor: "pointer", background: BRAND.white, transition: "all 0.2s", fontSize: 13, fontWeight: 700, color: BRAND.black, gap: 8 }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = BRAND.teal; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = BRAND.greyLight; }}>
            <input type="file" accept="image/*" multiple onChange={handleImagesUpload} style={{ display: "none" }} />
            {Icons.plus} Add photos
          </label>
        </div>

        {/* Videos */}
        <div>
          <label className="ll-label">Videos</label>
          <p style={{ fontSize: 11, color: BRAND.grey, marginBottom: 8 }}>Paste YouTube or TikTok links. YouTube videos embed directly; TikTok shows as a link.</p>
          {form.videos.length > 0 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 12 }}>
              {form.videos.map((url, i) => (
                <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", background: BRAND.offWhite, borderRadius: 6, fontSize: 13 }}>
                  <div style={{ flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: BRAND.grey }}>{url}</div>
                  <button className="icon-btn" style={{ color: "#dc2626", flexShrink: 0 }} onClick={() => removeVideo(i)}>{Icons.trash}</button>
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8 }}>
            <input className="ll-input" value={newVideo} onChange={e => setNewVideo(e.target.value)} placeholder="https://youtube.com/watch?v=... or TikTok link" onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); addVideo(); } }} style={{ flex: 1 }} />
            <button className="ll-btn ll-btn-primary ll-btn-sm" onClick={addVideo}>Add</button>
          </div>
        </div>

        {/* Save */}
        <div style={{ display: "flex", gap: 12, marginTop: 16 }}>
          <button className="ll-btn ll-btn-primary" style={{ flex: 1, justifyContent: "center" }} onClick={() => { if (form.title.trim()) onSave(form); }}>
            {form.id ? "Update Post" : "Publish Post"}
          </button>
          <button className="ll-btn ll-btn-outline" onClick={onCancel}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

